function magnitudeOrderBossReceipt(readings, k) {
  const a=readings; let out=[];
  out=[...a].sort((x,y)=>Math.abs(x)-Math.abs(y)||x-y);
  return out.reduce((s,x,i)=>s+(i+1)*x,0);
}

